export default function MenuCard({ item, addToCart }) {
  const isTopRated = item.avg_rating >= 4.5;
  const isPopular = item.sold >= 10; // threshold (adjust if needed)

  return (
    <div className="menu-card">
      <div className="menu-badges">
        {isPopular && <span className="badge popular">🔥 Popular</span>}
        {isTopRated && <span className="badge rated">⭐ Top Rated</span>}
      </div>

      <h3>{item.name}</h3>

      <p className="price">₹{item.price}</p>

      <p className="rating">
        ⭐ {item.avg_rating || 0} | Sold: {item.sold}
      </p>

      <p className={`stock ${item.stock === 0 ? "out" : ""}`}>
        {item.stock > 0 ? `Stock: ${item.stock}` : "Out of Stock"}
      </p>

      <button
        disabled={item.stock === 0}
        className="add-btn"
        onClick={() => addToCart(item)}
      >
        {item.stock === 0 ? "Unavailable" : "Add to Cart"}
      </button>
    </div>
  );
}
